#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <malloc.h>

#define MAX_MODULES 5000
#define MAX_NAME_LEN 64

/* Array of pointers to dynamically allocated strings */
char *modules[MAX_MODULES];
int module_count = 0;

/* Moved to global scope to prevent stack overflow (R6000) in 16-bit DOS */
char line[1024];
char out_filename[128];
char target_lib[128];

/* Comparison function for qsort */
int compare_modules(const void *a, const void *b) {
    return strcmp(*(char **)a, *(char **)b);
}

/* Display tool information and usage */
void print_usage(const char *progname) {
    printf(" LIB util - Library Extraction Parser\n");
    printf("======================================\n");
    printf("This tool reads a library listing file (generated by LIB.EXE) and\n");
    printf("creates a formatted response file to extract all internal modules.\n\n");
    printf("Usage: %s <input_list_file>\n\n", progname);
    printf("Example:\n");
    printf("  %s SLIBCE.LST\n", progname);
}

int main(int argc, char *argv[]) {
    FILE *in;
    FILE *out;
    char *newline;
    int i;
    int unique_count;
    int current_line_len;

    /* Check for missing command line arguments */
    if (argc < 2) {
        print_usage(argv[0]);
        return 1;
    }

    in = fopen(argv[1], "r");
    if (!in) {
        printf("Error: Could not open input file '%s'\n", argv[1]);
        return 1;
    }

    while (fgets(line, sizeof(line), in)) {
        char *ptr = line;
        while (*ptr) {
            /* Look for at least two consecutive dots */
            if (ptr[0] == '.' && ptr[1] == '.') {
                int len = 0;
                char mod_name[MAX_NAME_LEN];

                /* Skip past all consecutive dots */
                while (*ptr == '.') {
                    ptr++;
                }

                /* Extract the alphanumeric module name */
                while (*ptr && (isalnum((unsigned char)*ptr) || *ptr == '_' || *ptr == '-')) {
                    if (len < MAX_NAME_LEN - 1) {
                        mod_name[len++] = *ptr;
                    }
                    ptr++;
                }
                mod_name[len] = '\0';
                
                /* Dynamically allocate to save default near-heap space */
                if (len > 0 && module_count < MAX_MODULES) {
                    modules[module_count] = (char *)malloc(len + 1);
                    if (modules[module_count]) {
                        strcpy(modules[module_count], mod_name);
                        module_count++;
                    } else {
                        printf("Out of memory at module %d!\n", module_count);
                        fclose(in);
                        return 1;
                    }
                }
            } else {
                ptr++;
            }
        }
    }
    fclose(in);

    if (module_count == 0) {
        printf("No modules found in the listing file '%s'.\n", argv[1]);
        return 0;
    }

    /* Sort the array alphabetically to group duplicates */
    qsort(modules, module_count, sizeof(char *), compare_modules);

    printf("Successfully parsed %d total modules.\n", module_count);

    /* Prompt for the output response file name */
    printf("Enter the output response file name (e.g., EXTRACT.RSP): ");
    if (fgets(out_filename, sizeof(out_filename), stdin)) {
        newline = strchr(out_filename, '\n');
        if (newline) *newline = '\0';
    }
    /* Fallback if user just hits Enter */
    if (out_filename[0] == '\0') {
        strcpy(out_filename, "EXTRACT.RSP");
    }

    /* Prompt for the target library name to write in the file */
    printf("Enter the target library name for the response file (e.g., SLIBCE.LIB): ");
    if (fgets(target_lib, sizeof(target_lib), stdin)) {
        newline = strchr(target_lib, '\n');
        if (newline) *newline = '\0';
    }
    if (target_lib[0] == '\0') {
        strcpy(target_lib, "TARGET.LIB");
    }

    out = fopen(out_filename, "w");
    if (!out) {
        printf("Error creating %s\n", out_filename);
        return 1;
    }

    /* Write the target library on the first line */
    fprintf(out, "%s\n", target_lib);
    
    fprintf(out, "*%s", modules[0]);
    current_line_len = 1 + strlen(modules[0]);
    unique_count = 1;

    for (i = 1; i < module_count; i++) {
        /* Only write the module if it differs from the previous one */
        if (strcmp(modules[i], modules[i - 1]) != 0) {
            int add_len = 2 + strlen(modules[i]);
            
            /* Break lines at ~80 characters using MS-DOS LIB continuation '&' */
            if (current_line_len + add_len > 80) {
                fprintf(out, " &\n*%s", modules[i]);
                current_line_len = 1 + strlen(modules[i]);
            } else {
                fprintf(out, " *%s", modules[i]);
                current_line_len += add_len;
            }
            unique_count++;
        }
    }
    fprintf(out, ";\n");

    fclose(out);
    
    /* Clean up allocated memory */
    for (i = 0; i < module_count; i++) {
        free(modules[i]);
    }

    printf("Success! Wrote %d unique modules to %s.\n", unique_count, out_filename);
    return 0;
}